 5	final class PrimsMinimumSpanningTree implements MinimumSpanningTreeAlgorithm {
 6	    @Override
 7	    public MstResult compute(Graph graph) {
 8	        int vertexCount = graph.vertexCount();
 9	        int[] parentByVertex = new int[vertexCount];
10	        int[] bestWeightByVertex = new int[vertexCount];
11	        boolean[] includedInTree = new boolean[vertexCount];
12	
13	        Arrays.fill(parentByVertex, -1);
14	        Arrays.fill(bestWeightByVertex, Integer.MAX_VALUE);
15	        bestWeightByVertex[0] = 0;
16	
17	        for (int visitedVertices = 0; visitedVertices < vertexCount; visitedVertices++) {
18	            int currentVertex = selectNextVertex(bestWeightByVertex, includedInTree);
19	            if (currentVertex == -1) {
20	                throw new IllegalStateException("Graph must be connected.");
21	            }
22	
23	            includedInTree[currentVertex] = true;
24	            relaxAdjacentVertices(graph, currentVertex, parentByVertex, bestWeightByVertex, includedInTree);
25	        }
26	
27	        return buildResult(parentByVertex, bestWeightByVertex);
28	    }
29	
30	    private static int selectNextVertex(int[] bestWeightByVertex, boolean[] includedInTree) {
31	        int lightestWeight = Integer.MAX_VALUE;
32	        int selectedVertex = -1;
33	
34	        for (int vertex = 0; vertex < includedInTree.length; vertex++) {
35	            if (!includedInTree[vertex] && bestWeightByVertex[vertex] < lightestWeight) {
36	                lightestWeight = bestWeightByVertex[vertex];
37	                selectedVertex = vertex;
38	            }
39	        }
40	
41	        return selectedVertex;
42	    }
43	
44	    private static void relaxAdjacentVertices(
45	            Graph graph,
46	            int currentVertex,
47	            int[] parentByVertex,
48	            int[] bestWeightByVertex,
49	            boolean[] includedInTree) {
50	        for (Neighbor neighbor : graph.neighborsOf(currentVertex)) {
51	            int candidateVertex = neighbor.vertex();
52	            if (includedInTree[candidateVertex]) {
53	                continue;
54	            }
55	
56	            int candidateWeight = neighbor.weight();
57	            if (candidateWeight < bestWeightByVertex[candidateVertex]) {
58	                parentByVertex[candidateVertex] = currentVertex;
59	                bestWeightByVertex[candidateVertex] = candidateWeight;
60	            }
61	        }
62	    }
63	
64	    private static MstResult buildResult(int[] parentByVertex, int[] bestWeightByVertex) {
65	        List<Edge> edges = new ArrayList<>();
66	
67	        for (int vertex = 1; vertex < parentByVertex.length; vertex++) {
68	            int parentVertex = parentByVertex[vertex];
69	            if (parentVertex == -1) {
70	                throw new IllegalStateException("Graph must be connected.");
71	            }
72	
73	            edges.add(new Edge(parentVertex, vertex, bestWeightByVertex[vertex]));
74	        }
75	
76	        return new MstResult(edges);
77	    }
78	}

 1	final class PrimsMinimumSpanningTree implements MinimumSpanningTreeAlgorithm {
 2	    private static final int START_VERTEX = 0;
 3	
 4	    @Override
 5	    public MstResult compute(Graph graph) {
 6	        PrimVertexState vertexState = new PrimVertexState(graph.vertexCount(), START_VERTEX);
 7	
 8	        for (int visitedVertices = 0; visitedVertices < graph.vertexCount(); visitedVertices++) {
 9	            int currentVertex = vertexState.nextVertexToInclude();
10	            if (currentVertex == -1) {
11	                throw new IllegalStateException("Graph must be connected.");
12	            }
13	
14	            vertexState.include(currentVertex);
15	            relaxAdjacentVertices(graph, currentVertex, vertexState);
16	        }
17	
18	        return vertexState.buildResult();
19	    }
20	
21	    private static void relaxAdjacentVertices(Graph graph, int currentVertex, PrimVertexState vertexState) {
22	        for (Neighbor neighbor : graph.neighborsOf(currentVertex)) {
23	            int candidateVertex = neighbor.vertex();
24	            if (vertexState.isIncluded(candidateVertex)) {
25	                continue;
26	            }
27	
28	            vertexState.considerEdge(currentVertex, candidateVertex, neighbor.weight());
29	        }
30	    }
31	}

