 5	final class PrimVertexState {
 6	    private static final int NO_PARENT = -1;
 7	
 8	    private final int[] parentByVertex;
 9	    private final int[] bestWeightByVertex;
10	    private final boolean[] includedVertices;
11	
12	    PrimVertexState(int vertexCount, int startVertex) {
13	        parentByVertex = new int[vertexCount];
14	        bestWeightByVertex = new int[vertexCount];
15	        includedVertices = new boolean[vertexCount];
16	
17	        Arrays.fill(parentByVertex, NO_PARENT);
18	        Arrays.fill(bestWeightByVertex, Integer.MAX_VALUE);
19	        bestWeightByVertex[startVertex] = 0;
20	    }
21	
22	    int nextVertexToInclude() {
23	        int lightestWeight = Integer.MAX_VALUE;
24	        int selectedVertex = -1;
25	
26	        for (int vertex = 0; vertex < includedVertices.length; vertex++) {
27	            if (!includedVertices[vertex] && bestWeightByVertex[vertex] < lightestWeight) {
28	                lightestWeight = bestWeightByVertex[vertex];
29	                selectedVertex = vertex;
30	            }
31	        }
32	
33	        return selectedVertex;
34	    }
35	
36	    void include(int vertex) {
37	        includedVertices[vertex] = true;
38	    }
39	
40	    boolean isIncluded(int vertex) {
41	        return includedVertices[vertex];
42	    }
43	
44	    void considerEdge(int fromVertex, int toVertex, int weight) {
45	        if (weight < bestWeightByVertex[toVertex]) {
46	            parentByVertex[toVertex] = fromVertex;
47	            bestWeightByVertex[toVertex] = weight;
48	        }
49	    }
50	
51	    MstResult buildResult() {
52	        List<Edge> edges = new ArrayList<>();
53	
54	        for (int vertex = 1; vertex < parentByVertex.length; vertex++) {
55	            int parentVertex = parentByVertex[vertex];
56	            if (parentVertex == NO_PARENT) {
57	                throw new IllegalStateException("Graph must be connected.");
58	            }
59	
60	            edges.add(new Edge(parentVertex, vertex, bestWeightByVertex[vertex]));
61	        }
62	
63	        return MstResult.fromEdges(edges);
64	    }
65	}

