 3	record MstResult(List<Edge> edges, int totalWeight) {
 4	    MstResult {
 5	        edges = List.copyOf(edges);
 6	    }
 7	
 8	    static MstResult fromEdges(List<Edge> edges) {
 9	        return new MstResult(edges, calculateTotalWeight(edges));
10	    }
11	
12	    private static int calculateTotalWeight(List<Edge> edges) {
13	        int totalWeight = 0;
14	        for (Edge edge : edges) {
15	            totalWeight += edge.weight();
16	        }
17	        return totalWeight;
18	    }
19	}

